import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第34章 没来成","description":"","frontmatter":{},"headers":[],"relativePath":"第34章_没来成.md","filePath":"第34章_没来成.md"}'),o={name:"第34章_没来成.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第34章-没来成" tabindex="-1">第34章 没来成 <a class="header-anchor" href="#第34章-没来成" aria-label="Permalink to &quot;第34章 没来成&quot;">​</a></h1><p>腊月二十，她本来要来南雾。</p><p>这事是十二月底说定的。她说她想看看他长大的地方是什么样。她说她想看那条河，看他说过的桥，看他奶奶住的那栋楼。</p><p>我说好。</p><p>我说你来就是了，我下车接你。</p><p>她说不用，她自己坐车。</p><p>我说那不行。</p><p>她说你站在远处就行了，别在车站等我。</p><p>我说为什么。</p><p>她说，万一有人认得我。</p><p>我说，没人认得你。</p><p>她说，你不懂。</p><p>我就说，那我在河边等你。</p><p>她说，好。</p><p>那天早上我很早就醒了。奶奶在煮东西，厨房里全是白汽。我穿了两件衣服，把围巾带上，出门的时候她说吃了再走。我说等下回来吃。</p><p>班车一天只有几趟。九点一刻一趟，十一点一趟，下午两点一趟，四点还有一趟。我在家里翻着那张时刻表看了很久。</p><p>九点一刻那趟车到站的时候，我站在桥这头。</p><p>车门开了，下来四个人。三个是大人，一个背着画板的。没有人往桥这边看。</p><p>我等到车开走，才想起来我根本不知道她今天穿什么。</p><p>我们说过那么多话，没说过衣服。</p><p>我在石凳上坐着，把手机拿出来看了一次。屏幕上没有新东西。</p><p>石凳是冷的。坐久了裤子上会有一层湿。河在这个季节很浅，石头上有青苔，滑的。风从水面上过来，吹得人想缩。</p><p>河边有一个卖河粉的小棚子，平时十点开，今天开得早。我在那里买了一碗，站着吃完。</p><p>老板在收桌子，看见我还站在那里，问我要不要再加个蛋。</p><p>我说不要。</p><p>他说，等人啊。</p><p>我说是。</p><p>他把桌子抹了一遍，说，等人最怕的不是等，是你不知道你要等的是哪个。</p><p>我那时没接话。</p><p>后来这句话我一直记得。我那天站在河边，确实不知道我接的是哪一辆车、哪一个人、什么衣服。我们说了那么多话，从来没说过这些。</p><p>十一点那趟车。我站着看。</p><p>下来五个人。都不是。</p><p>回去吃了一碗面，没吃出味道。奶奶问我是不是不舒服。我说没有。她又问是不是等什么人。我说没有。</p><p>她说，那你出去坐着干什么。</p><p>我说，走走。</p><p>她说，外头冷。</p><p>我说，不冷。</p><p>下午两点那趟。四点那趟。</p><p>中间我回河边那个棚子又买了一碗河粉。老板认得我，问我还等呢。</p><p>我说，还等。</p><p>他说，那你坐里面，风大。</p><p>我说不不用。</p><p>我说，我在外头看得清楚。</p><p>其实里面只能看到车的尾部。我在外面能看到整条路。</p><p>四点的车到站的时候，天已经开始暗了。南雾的冬天下午五点就没光了。我看着车上的灯亮起来，看着它停稳，看着车门开。</p><p>下来两个人。</p><p>都不是。</p><p>我在石凳上坐到路灯亮起来。河对面那栋楼的灯一格一格亮着，有人在阳台收衣服，收完把一根衣架随手挂在了栏杆上。</p><p>我给她发了一条。</p><p>我说，今天几点的车。</p><p>发出去我就后悔了。她要是来，早就该到了。</p><p>我把手机翻过来扣在腿上，等着。</p><p>风把河面上的水汽吹过来，吹到我脸上是湿的。我把围巾往上拉了一点。</p><p>过了很久，屏幕亮了一下。</p><p>她说，对不起。</p><p>她说，我明天跟你说。</p><p>我看到这两句，心里先松了一下。松的是她还说话。紧的是那句&quot;明天再说&quot;。</p><p>我回：好。</p><p>我回：你明天一定告诉我。</p><p>她没回。</p><p>我站起来往回走。走到巷口的时候我抬头看了一眼我家那扇窗，灯亮着，窗帘上有一个影子，是奶奶在收桌子。</p><p>走到半路我想起一件事。</p><p>她以前说过一次，说她那边河粉多到吃不完，吃的想呕。</p><p>她说那话的时候语气很轻，像在抱怨一个小事。</p><p>我今天在河边吃了两碗。</p><p>那天晚上她没有上线。</p><p>第二天也没有。</p><p>第三天她来了一句，说她家里有事。</p><p>我问要不要紧。</p><p>她说，不要紧，就是来不了了。</p><p>我问什么时候能来。</p><p>她说，不知道。</p><p>我说，那等过年以后。</p><p>她说，好。</p><p>我说，你忙你的。</p><p>她说，你别生我气。</p><p>我看着这一句，想了很久。</p><p>我当然生气。我在石凳上坐了整整一天，四趟车，我每一趟都数过。</p><p>可我回的是：没有。</p><p>我说，我没有生气。</p><p>我说，你先顾家里。</p><p>我说，我不着急。</p><p>她回了一个字：好。</p><p>就这一个字。以后又断了四天。</p><p>那四天里我做了一件现在想起来很傻的事。</p><p>我把那天下午看见的东西全写了下来。</p><p>九点一刻，下车四个人，三个大人，一个背画板的。</p><p>十一点，下车五个人，其中一个女的穿红色的羽绒。</p><p>两点，下车三个人。</p><p>四点，下车两个人。</p><p>我写得很细。写完之后我看着那四行字，发现我在做的事是：把一件发生了但什么也没发生的事，同证据一样固定下来。</p><p>因为没有人会信我。她自己都不会信。</p><p>她只会以为我在家里睡了一下午。</p><p>第五天她上线，第一句话是：你今天去哪了。</p><p>我说，没去哪。</p><p>她说，你是不是去河边了。</p><p>我拿着手机，坐在那里没动。</p><p>我说，没有。</p><p>她说，你别骗我。</p><p>我说，我去了一下。</p><p>她说，什么时候。</p><p>我说，就坐了一会儿。</p><p>她隔了很久才回。</p><p>她说，我对不起你。</p><p>我说，没事。</p><p>她说，我不信你说没事。</p><p>那天夜里我把买好的那张回程票从钱包里抽出来。</p><p>票是提前买的，腊月二十一从南雾回雾山，下午三点，靠窗。</p><p>我本来打算让她回去的时候靠窗坐着，能看见那条河。</p><p>我拿着它看了很久。</p><p>我没退。</p><p>不是退不掉，窗口说拿身份证就能退。我没退是因为，退了这张纸就没了。纸没了，那天下午就只剩下我一个人记得。</p><p>我把它夹进了本子。</p><p>本子那时候已经夹了两张纸。练习册里一张卡，抽屉里一个瓶盖。现在又多了一张票。</p><p>那天晚上我想明白了一件事，想得很清楚。</p><p>我在留东西。她在删东西。</p><p>这个区别我们当时谁都没看见。后来它变成了我们之间唯一的问题。</p>',117)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
